                GenerationProgressHub.Report(isFullRetry ? $"AI未返回内容，第{attempt + 1}次重新生成..."
                    : isRewrite ? $"校验未通过，开始第{attempt + 1}次重写..."
                    : "正在调用AI生成内容...");

                string userPrompt;
                if (!isRewrite || previousFailures.Count == 0)
                {
