                                    TM.App.Log($"[AutoRewriteEngine] 润色导致蓝图合规退步({missingItems.Count}→{origMissing.Count})，回退到原文");
                                    GenerationProgressHub.Report("⚠ 润色导致蓝图退步，使用原文");
                                    goto bp_passed;
                                }
