        private static int ImportanceScore(PlotPointEntry p)
        {
            var score = p.Importance switch
            {
                "critical" => 3,
                "important" => 2,
                _ => 1
            };
            if (string.Equals(p.Storyline, "main", StringComparison.OrdinalIgnoreCase))
                score += 2;
            return score;
        }

