                var loaded = JsonSerializer.Deserialize<StructuredMemory>(json, _jsonOptions);
                if (loaded != null)
                {
                    _memory = loaded;
                    TM.App.Log($"[StructuredMemoryExtractor] 记忆已加载: {filePath}");
