        private async Task<int> UpdateManifestAsync()
        {
            var manifest = GetManifest() ?? new ManifestInfo();

            var currentSourceBookId = await _workScopeService.GetCurrentScopeAsync();

            if (string.IsNullOrEmpty(currentSourceBookId))
            {
