            builtInUpdated = false;
            foreach (var category in Categories)
            {
                if (!EnsureCategoryId(category, category.IsBuiltIn))
                {
                    continue;
                }

                if (category.IsBuiltIn)
                {
                    builtInUpdated = true;
                }
                else
                {
                    updated = true;
                }
            }

            return updated;
